'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import type { Incident } from '@/lib/database.types';

// ── Realistic incident pool ──────────────────────────────────────────
const INCIDENT_POOL = [
    { source: 'Database Connection Exhaustion', severity: 'critical' as const },
    { source: 'Auth Service Latency Spike', severity: 'warning' as const },
    { source: 'Redis OOM: Cache Eviction Failure', severity: 'critical' as const },
    { source: 'S3 Bucket Permission Denied', severity: 'warning' as const },
    { source: 'Stripe API Timeout (Payment Gateway)', severity: 'critical' as const },
];

// ── Risk tier mapping ────────────────────────────────────────────────
type RiskTier = 'high' | 'medium' | 'low';

function getRiskTier(severity: Incident['severity']): { tier: RiskTier; cls: string; label: string } {
    const map = {
        critical: { tier: 'high' as const, cls: 'sg-risk-high', label: 'HIGH RISK' },
        warning: { tier: 'medium' as const, cls: 'sg-risk-medium', label: 'MEDIUM RISK' },
        info: { tier: 'low' as const, cls: 'sg-risk-low', label: 'LOW RISK' },
    };
    return map[severity] ?? map.info;
}

function getActionBadge(status: Incident['status']): { cls: string; label: string; dot: string } {
    if (status === 'resolved') return { cls: 'sg-action-resolved', label: 'RESOLVED', dot: 'bg-action-resolved' };
    if (status === 'pending_approval') return { cls: 'sg-action-pending', label: 'PENDING APPROVAL', dot: 'bg-action-pending' };
    if (status === 'failed') return { cls: 'sg-badge-critical', label: 'FAILED', dot: 'bg-critical' };
    return { cls: 'sg-badge-info', label: status.replace(/_/g, ' ').toUpperCase(), dot: 'bg-secondary' };
}

function timeAgo(dateStr: string): string {
    const diff = Date.now() - new Date(dateStr).getTime();
    const secs = Math.floor(diff / 1000);
    if (secs < 60) return `${secs}s ago`;
    const mins = Math.floor(secs / 60);
    if (mins < 60) return `${mins}m ago`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `${hrs}h ago`;
    return `${Math.floor(hrs / 24)}d ago`;
}

// ── Metric Card ──────────────────────────────────────────────────────
function MetricCard({ label, value, subtext, color }: {
    label: string; value: string | number; subtext?: string; color?: string;
}) {
    return (
        <div className="sg-card flex flex-col gap-1.5">
            <span className="text-[10px] text-text-muted uppercase tracking-[0.12em] font-semibold">{label}</span>
            <span className={`text-3xl font-bold font-mono ${color ?? 'text-text-primary'}`}>{value}</span>
            {subtext && <span className="text-[11px] text-text-muted">{subtext}</span>}
        </div>
    );
}

// ── Incident Row ─────────────────────────────────────────────────────
function IncidentRow({ incident, onClick }: { incident: Incident; onClick: () => void }) {
    const risk = getRiskTier(incident.severity);
    const action = getActionBadge(incident.status);
    const isActive = !['resolved', 'failed'].includes(incident.status);

    return (
        <div
            onClick={onClick}
            className={`
                flex items-center gap-4 px-4 py-3.5 rounded-lg cursor-pointer transition-all duration-200
                border ${isActive ? 'border-border-bright/50' : 'border-border/30'} 
                bg-surface hover:bg-surface-2 hover:border-primary/30 group
            `}
        >
            <span className={`w-2 h-2 rounded-full flex-shrink-0 ${risk.tier === 'high' ? 'bg-risk-high animate-pulse' : risk.tier === 'medium' ? 'bg-risk-medium' : 'bg-risk-low'}`} />
            <span className="flex-1 text-sm text-text-primary group-hover:text-white truncate font-medium">
                {incident.source}
            </span>
            <span className={risk.cls}>{risk.label}</span>
            <span className={action.cls}>{action.label}</span>
            <span className="text-[11px] text-text-muted min-w-[60px] text-right font-mono">
                {timeAgo(incident.created_at)}
            </span>
        </div>
    );
}

