// ── Agent Learnings Hub Component ────────────────────────────────────
function AgentLearningsHub() {
    const [overrideLearnings, setOverrideLearnings] = useState<Array<{
        id: string;
        timestamp: string;
        pattern: string;
        strategy: string;
        prevention: string;
        confidence: number;
        incidents: number;
        isOverride: boolean;
    }>>([]);

    useEffect(() => {
        async function fetchOverrides() {
            try {
                const res = await fetch('/api/incidents');
                if (!res.ok) return;
                const incidents = await res.json() as Incident[];
                const resolvedRecent = incidents
                    .filter(i => i.status === 'resolved')
                    .slice(0, 5);

                const overrides: typeof overrideLearnings = [];

                for (const inc of resolvedRecent) {
                    try {
                        const detailRes = await fetch(`/api/incidents/${inc.id}`);
                        if (!detailRes.ok) continue;
                        const detail = await detailRes.json() as {
                            auditLogs: Array<{ action_taken: string; result: unknown; created_at: string }>;
                        };
                        const overrideLog = detail.auditLogs?.find(a => a.action_taken.startsWith('OVERRIDE:'));
                        if (overrideLog && overrideLog.result) {
                            const result = overrideLog.result as { original?: string; selected?: string; message?: string };
                            overrides.push({
                                id: `override-${inc.id}`,
                                timestamp: timeAgo(overrideLog.created_at),
                                pattern: `User overridden: Preferred [${result.selected || 'custom action'}] over [${result.original || 'agent suggestion'}]. Updating bias for similar incidents.`,
                                strategy: `Apply "${result.selected || 'user selection'}" as the primary response for ${inc.source} events.`,
                                prevention: `Decision logged to agent training corpus. Future incidents matching "${inc.source}" will weight user-preferred action higher.`,
                                confidence: 0.99,
                                incidents: 1,
                                isOverride: true,
                            });
                        }
                    } catch { /* skip */ }
                }

                setOverrideLearnings(overrides);
            } catch { /* skip */ }
        }

        fetchOverrides();
        const interval = setInterval(fetchOverrides, 5000);
        return () => clearInterval(interval);
    }, []);

    const allLearnings = [...overrideLearnings, ...MOCK_LEARNINGS.map(l => ({ ...l, isOverride: false }))];
    const totalIncidents = allLearnings.reduce((a, l) => a + l.incidents, 0);

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-lg font-bold text-text-primary flex items-center gap-3 header-glow">
                        <span className="w-8 h-8 rounded-lg bg-primary/15 border border-primary/30 flex items-center justify-center text-primary text-sm">🧠</span>
                        Agent Learnings Hub
                    </h2>
                    <p className="text-xs text-text-muted mt-1">Patterns recognized across {totalIncidents} incidents — the agent&apos;s persistent journal of wisdom</p>
                </div>
                <div className="flex items-center gap-2 text-xs text-text-muted font-mono">
                    <span className="w-2 h-2 rounded-full bg-safe animate-pulse" />
                    {allLearnings.length} patterns learned
                    {overrideLearnings.length > 0 && (
                        <span className="ml-2 px-1.5 py-0.5 rounded-full bg-action-pending/20 text-action-pending text-[9px] font-semibold">
                            {overrideLearnings.length} override{overrideLearnings.length > 1 ? 's' : ''}
                        </span>
                    )}
                </div>
            </div>

            <div className="relative">
                <div className="absolute left-[19px] top-0 bottom-0 w-px bg-gradient-to-b from-primary/40 via-secondary/20 to-transparent" />
                <div className="space-y-4">
                    {allLearnings.map((learning, idx) => (
                        <div key={learning.id} className="relative pl-12 animate-fade-in" style={{ animationDelay: `${idx * 100}ms` }}>
                            <div className={`absolute left-[12px] top-5 w-[15px] h-[15px] rounded-full border-2 ${learning.isOverride ? 'border-action-pending/80 bg-action-pending/10' : 'border-primary/60 bg-background'} flex items-center justify-center`}>
                                <div className={`w-[5px] h-[5px] rounded-full ${learning.isOverride ? 'bg-action-pending' : 'bg-primary'}`} />
                            </div>

                            <div className={`sg-learning-card ${learning.isOverride ? 'border-action-pending/30 shadow-[0_0_15px_rgba(234,179,8,0.06)]' : ''}`}>
                                <div className="flex items-center justify-between mb-4">
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-mono text-text-muted">{learning.timestamp}</span>
                                        {learning.isOverride && (
                                            <span className="px-1.5 py-0.5 rounded-full bg-action-pending/20 text-action-pending text-[8px] font-bold uppercase tracking-wider">
                                                Human Override
                                            </span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <span className="text-[10px] font-mono text-text-muted">{learning.incidents} incident{learning.incidents !== 1 ? 's' : ''}</span>
                                        <div className="flex items-center gap-1.5">
                                            <div className="w-16 h-1 rounded-full bg-surface-3 overflow-hidden">
                                                <div className={`h-full rounded-full transition-all duration-1000 ${learning.isOverride ? 'bg-action-pending' : 'bg-primary'}`} style={{ width: `${learning.confidence * 100}%` }} />
                                            </div>
                                            <span className={`text-[10px] font-mono ${learning.isOverride ? 'text-action-pending' : 'text-primary'}`}>{Math.round(learning.confidence * 100)}%</span>
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-3">
                                    <div>
                                        <div className="sg-verdict-label">
                                            <span className={`w-1 h-1 rounded-full ${learning.isOverride ? 'bg-action-pending' : 'bg-risk-high'}`} />
                                            {learning.isOverride ? 'Decision Override Logged' : 'Pattern Recognized'}
                                        </div>
                                        <p className="text-sm text-text-primary leading-relaxed">{learning.pattern}</p>
                                    </div>

                                    <div>
                                        <div className="sg-verdict-label">
                                            <span className="w-1 h-1 rounded-full bg-safe" />
                                            Healing Strategy
                                        </div>
                                        <p className="text-sm text-text-secondary leading-relaxed">{learning.strategy}</p>
                                    </div>

                                    <div>
                                        <div className="sg-verdict-label">
                                            <span className="w-1 h-1 rounded-full bg-primary" />
                                            Global Prevention
                                        </div>
                                        <p className="text-sm text-text-secondary leading-relaxed">{learning.prevention}</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}


// ── Main Dashboard ───────────────────────────────────────────────────
export default function DashboardPage() {
    const [incidents, setIncidents] = useState<Incident[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState<'all' | 'active' | 'resolved'>('all');
    const [activeTab, setActiveTab] = useState<'situation' | 'learnings'>('situation');
    const [triggerStatus, setTriggerStatus] = useState<string | null>(null);
    const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

    const fetchIncidents = useCallback(async () => {
        try {
            const res = await fetch('/api/incidents');
            if (res.ok) {
                const data = await res.json() as Incident[];
                setIncidents(data);
            }
        } catch {
            // next poll retries
        }
        setLoading(false);
    }, []);

    useEffect(() => { fetchIncidents(); }, [fetchIncidents]);

    useEffect(() => {
        pollRef.current = setInterval(fetchIncidents, 3000);
        return () => { if (pollRef.current) clearInterval(pollRef.current); };
    }, [fetchIncidents]);

    const filtered = incidents.filter(i => {
        if (filter === 'active') return !['resolved', 'failed'].includes(i.status);
        if (filter === 'resolved') return i.status === 'resolved';
        return true;
    });

    const activeCount = incidents.filter(i => !['resolved', 'failed'].includes(i.status)).length;
    const pendingCount = incidents.filter(i => i.status === 'pending_approval').length;
    const resolvedCount = incidents.filter(i => i.status === 'resolved').length;
    const highRiskCount = incidents.filter(i => i.severity === 'critical').length;

    async function fireMockIncident() {
        setTriggerStatus('Firing...');
        try {
            const shuffled = [...INCIDENT_POOL].sort(() => Math.random() - 0.5);
            const picks = shuffled.slice(0, 2);

            const results = await Promise.all(
                picks.map(pick =>
                    fetch('/api/webhook', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            source: pick.source,
                            severity: pick.severity,
                            idempotency_key: `mock-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`,
                            metadata: {
                                cpu_percent: Math.round(30 + Math.random() * 70),
                                memory_percent: Math.round(40 + Math.random() * 55),
                                rps: Math.round(800 + Math.random() * 4200),
                                error_rate: +(Math.random() * 0.08).toFixed(4),
                                latency_p99_ms: Math.round(200 + Math.random() * 1800),
                            },
                        }),
                    }).then(r => r.json() as Promise<{ status?: string; error?: string }>)
                )
            );

            const anySuccess = results.some(r => r.status === 'processed' || r.status === 'safe_mode');
            if (anySuccess) {
                setTriggerStatus('✅ 2 incidents deployed');
                fetchIncidents();
            } else {
                setTriggerStatus(`⚠️ ${results[0]?.error ?? 'Unknown'}`);
            }
            setTimeout(() => setTriggerStatus(null), 4000);
        } catch (e) {
            setTriggerStatus(`❌ ${(e as Error).message}`);
            setTimeout(() => setTriggerStatus(null), 4000);
        }
    }

    return (
        <div className="min-h-screen flex flex-col">
            {/* ── Top Bar ── */}
            <header className="sticky top-0 z-10 border-b border-border bg-background/95 backdrop-blur-sm">
                <div className="max-w-7xl mx-auto px-6 py-3 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-primary/15 border border-primary/30 flex items-center justify-center">
                            <svg className="w-4 h-4 text-primary" fill="currentColor" viewBox="0 0 24 24">
                                <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                        </div>
                        <div>
                            <h1 className="font-bold text-text-primary text-sm tracking-wide header-glow">SENTINEL GOVERNOR</h1>
                            <p className="text-[10px] text-text-muted font-mono uppercase tracking-widest">SG-1 // COMMAND CENTER</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-surface border border-border text-[11px] text-text-secondary">
                            <span className="w-1.5 h-1.5 rounded-full bg-safe animate-pulse" />
                            LIVE
                        </div>

                        <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full bg-primary/10 border border-primary/30 text-[11px] text-primary font-mono">
                            llama-3.3-70b
                        </div>

                        <button
                            onClick={fireMockIncident}
                            disabled={triggerStatus === 'Firing...'}
                            className="sg-btn-primary text-xs"
                            id="fire-mock-incident"
                        >
                            {triggerStatus ? (
                                <span className="text-[11px]">{triggerStatus}</span>
                            ) : (
                                <>
                                    <span>🚀</span>
                                    <span>Fire Mock Incident</span>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </header>

            <main className="flex-1 max-w-7xl mx-auto w-full px-6 py-6 space-y-6">
                {/* ── Tab Navigation ── */}
                <div className="flex items-center gap-2 bg-surface-2/50 rounded-xl p-1.5 w-fit">
                    <button
                        onClick={() => setActiveTab('situation')}
                        className={activeTab === 'situation' ? 'sg-tab-active' : 'sg-tab-inactive'}
                    >
                        Situation Room
                    </button>
                    <button
                        onClick={() => setActiveTab('learnings')}
                        className={activeTab === 'learnings' ? 'sg-tab-active' : 'sg-tab-inactive'}
                    >
                        Agent Learnings Hub
                    </button>
                </div>

                {activeTab === 'situation' ? (
                    <>
                        {/* ── Metric Cards ── */}
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <MetricCard label="Active" value={activeCount} subtext="Incidents in pipeline" color={activeCount > 0 ? 'text-warning' : 'text-text-primary'} />
                            <MetricCard label="Pending" value={pendingCount} subtext="Awaiting human approval" color={pendingCount > 0 ? 'text-action-pending' : 'text-text-primary'} />
                            <MetricCard label="Resolved" value={resolvedCount} subtext="Successfully resolved" color="text-action-resolved" />
                            <MetricCard label="High Risk" value={highRiskCount} subtext="Critical severity" color={highRiskCount > 0 ? 'text-risk-high' : 'text-text-primary'} />
                        </div>

                        {/* ── Incident List ── */}
                        <div className="sg-card space-y-4">
                            <div className="flex items-center justify-between">
                                <h2 className="font-semibold text-text-primary text-sm flex items-center gap-2 header-glow">
                                    <span>INCIDENT LOG</span>
                                    <span className="sg-badge-info">{filtered.length}</span>
                                </h2>
                                <div className="flex gap-1 bg-surface-2 rounded-lg p-1">
                                    {(['all', 'active', 'resolved'] as const).map(f => (
                                        <button
                                            key={f}
                                            onClick={() => setFilter(f)}
                                            className={`px-3 py-1 rounded-md text-xs font-semibold transition-all ${filter === f
                                                ? 'bg-primary text-white'
                                                : 'text-text-muted hover:text-text-secondary'
                                                }`}
                                        >
                                            {f.toUpperCase()}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {loading ? (
                                <div className="flex items-center justify-center py-16 text-text-muted">
                                    <div className="flex flex-col items-center gap-3">
                                        <div className="w-8 h-8 border-2 border-primary/30 border-t-primary rounded-full animate-spin" />
                                        <span className="text-xs font-mono">CONNECTING TO SUPABASE...</span>
                                    </div>
                                </div>
                            ) : filtered.length === 0 ? (
                                <div className="flex flex-col items-center justify-center py-16 gap-4 text-text-muted">
                                    <div className="w-12 h-12 rounded-xl bg-surface-2 border border-border flex items-center justify-center text-2xl">🛡️</div>
                                    <p className="text-sm">No incidents. Fire a mock incident to test SG-1.</p>
                                </div>
                            ) : (
                                <div className="space-y-2">
                                    {filtered.map(incident => (
                                        <IncidentRow
                                            key={incident.id}
                                            incident={incident}
                                            onClick={() => window.open(`/incidents/${incident.id}`, '_self')}
                                        />
                                    ))}
                                </div>
                            )}
                        </div>
                    </>
                ) : (
                    <AgentLearningsHub />
                )}
            </main>
        </div>
    );
}
